&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types de paladin&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_de_paladin_0&quot; href=&quot;#Les_arch&#233;types_de_paladin_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html&quot; title=&quot;Le paladin&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-B&#233;ni-(Paladin).html&quot; title=&quot;Bouclier b&#233;ni&quot;&gt;Bouclier b&#233;ni&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Champion-Du-Temple-(Paladin).html&quot; title=&quot;Champion du temple&quot;&gt;Champion du temple&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Champion-Temp&#233;r&#233;-(Paladin).html&quot; title=&quot;Champion temp&#233;r&#233;&quot;&gt;Champion temp&#233;r&#233;&lt;/a&gt; (&lt;i&gt;WMH&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-De-Fant&#244;mes-(Paladin).html&quot; title=&quot;Chasseur de fant&#244;mes&quot;&gt;Chasseur de fant&#244;mes&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-Divin-(Paladin).html&quot; title=&quot;Chasseur divin&quot;&gt;Chasseur divin&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-Des-Pi&#232;ces-(Paladin).html&quot; title=&quot;Chevalier des pi&#232;ces&quot;&gt;Chevalier des pi&#232;ces&lt;/a&gt; (MM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-Empyr&#233;en-(Paladin).html&quot; title=&quot;Chevalier empyr&#233;en&quot;&gt;Chevalier empyr&#233;en&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-&#201;tincelant-(Paladin).html&quot; title=&quot;Chevalier &#233;tincelant&quot;&gt;Chevalier &#233;tincelant&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fenseur-Divin-(Paladin).html&quot; title=&quot;D&#233;fenseur divin&quot;&gt;D&#233;fenseur divin&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Elu-(Paladin).html&quot; title=&quot;&#201;lu&quot;&gt;&#201;lu&lt;/a&gt; &lt;i&gt;(FF)&lt;/i&gt;&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;p&#233;e-Du-Courage-(Paladin).html&quot; title=&quot;&#201;p&#233;e du courage&quot;&gt;&#201;p&#233;e du courage&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fl&#233;au-Des-Morts-Vivants-(Paladin).html&quot; title=&quot;Fl&#233;au des morts-vivants&quot;&gt;Fl&#233;au des morts-vivants&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Glaive-De-Lesprit-(Paladin).html&quot; title=&quot;Glaive de l&amp;#39;esprit&quot;&gt;Glaive de l&#39;esprit&lt;/a&gt; (&lt;i&gt;OO&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier-De-La-Lumi&#232;re-Sainte-(Paladin).html&quot; title=&quot;Guerrier de la lumi&#232;re sainte&quot;&gt;Guerrier de la lumi&#232;re sainte&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guide-Saint-(Paladin).html&quot; title=&quot;Guide saint&quot;&gt;Guide saint&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Hospitalier-(Paladin).html&quot; title=&quot;Hospitalier&quot;&gt;Hospitalier&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;L&#233;gat-(Paladin).html&quot; title=&quot;L&#233;gat&quot;&gt;L&#233;gat&lt;/a&gt; (&lt;i&gt;AMH&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Paladin-Asserment&#233;-(Paladin).html&quot; title=&quot;Paladin asserment&#233;&quot;&gt;Paladin asserment&#233;&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Paladin-Gris-(Paladin).html&quot; title=&quot;Paladin gris&quot;&gt;Paladin gris&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;dempteur-(Paladin).html&quot; title=&quot;R&#233;dempteur&quot;&gt;R&#233;dempteur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Demi-Orque.html&quot; title=&quot;Les demi-orques&quot;&gt;Demi-orque&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sage-Gardien-(Paladin).html&quot; title=&quot;Sage gardien&quot;&gt;Sage gardien&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aasimar-(Race).html&quot; title=&quot;Les aasimars&quot;&gt;Aasimar&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Saint-Pistolet-(Paladin).html&quot; title=&quot;Saint pistolet&quot;&gt;Saint pistolet&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Saint-Tacticien-(Paladin).html&quot; title=&quot;Saint tacticien&quot;&gt;Saint tacticien&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Seigneur-De-Pierre-(Paladin).html&quot; title=&quot;Seigneur de pierre&quot;&gt;Seigneur de pierre&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Nain.html&quot; title=&quot;Les nains&quot;&gt;Nain&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Serviteur-Sacr&#233;-(Paladin).html&quot; title=&quot;Serviteur sacr&#233;&quot;&gt;Serviteur sacr&#233;&lt;/a&gt; (MJRA)&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;L&#39;antipaladin&lt;/a&gt; (classe alternative) (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-Du-S&#233;pulcre-(Paladin).html&quot; title=&quot;Chevalier du s&#233;pulcre&quot;&gt;Chevalier du s&#233;pulcre&lt;/a&gt; (UC)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Insinuateur-(Paladin).html&quot; title=&quot;Insinuateur&quot;&gt;Insinuateur&lt;/a&gt; &lt;i&gt;(AoE)&lt;/i&gt;&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Saccageur-(Paladin).html&quot; title=&quot;Saccageur&quot;&gt;Saccageur&lt;/a&gt; &lt;i&gt;(ISC)&lt;/i&gt;&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Semeur-De-Peur-(Antipaladin).html&quot; title=&quot;Semeur de peur&quot;&gt;Semeur de peur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gobelours.html&quot; title=&quot;Gobelours&quot;&gt;Gobelours&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tyran-(Antipaladin).html&quot; title=&quot;Tyran&quot;&gt;Tyran&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tyran-De-Fer-(Antipaladin).html&quot; title=&quot;Tyran de fer&quot;&gt;Tyran de fer&lt;/a&gt; (&lt;i&gt;AMH&lt;/i&gt;)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel du ma&#238;tre des armures (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Armor Master&#39;s Handbook/Manuel du ma&#238;tre des armures&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAMH.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Couvert de la t&#234;te aux pieds d’une armure ternie d&#233;cor&#233;e de formes grotesques et h&#233;riss&#233;es de pointes, les tyrans de fer font une impression ind&#233;niable sur le champ de bataille. Cette armure d&#39;antipaladin est une ext&#233;riorisation de leur pouvoir int&#233;rieur, et ils sont rarement vus sans. Les tyrans de fer recherchent la force de r&#233;gner sur des domaines en tant que despotes sans entraves et d&#233;pendent de leur armure pour se prot&#233;ger contre ceux qu&#39;ils n&#39;ont pas encore soumis. La plupart des tyrans de fer sont des orques ou demi-orques priant les divinit&#233;s orques Lanishara (dieu de l’assujettissement, de l&#39;esclavagisme et de la tyrannie) ou Varg (dieu des armes de si&#232;ges, du fer et de la guerre). Plus rarement, d’autres races peuvent &#234;tre des tyrans de fer, priant Urazra (dieu g&#233;ant des batailles, de la brutalit&#233; et de la force) ou des seigneurs d&#233;mons tel que Aldinach (La dame aux Six Venins), Angazhan (le Roi affam&#233;) ou Izyagne (Celle aux sept pullulements).&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;Cet arch&#233;type est seulement accessible &#224; la classe alternative d’&lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;antipaladin&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Poing de fer (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Poing_de_fer_Ext_0&quot; href=&quot;#Poing_de_fer_Ext_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 2, un tyran de fer gagne &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Combat-&#192;-Mains-Nues.html&quot; title=&quot;Science du combat &#224; mains nues&quot;&gt;Science du combat &#224; mains nues&lt;/a&gt; comme don suppl&#233;mentaire. De plus, quand un tyran de fer r&#233;ussit une attaque avec un &lt;a class=&quot;pagelink&quot; href=&quot;Gantelet-(Arme).html&quot; title=&quot;Gantelet&quot;&gt;gantelet&lt;/a&gt;, un &lt;a class=&quot;pagelink&quot; href=&quot;Gantelet-Clout&#233;-(Arme).html&quot; title=&quot;Gantelet clout&#233;&quot;&gt;gantelet clout&#233;&lt;/a&gt; ou des &lt;a class=&quot;pagelink&quot; href=&quot;Pointes-Darmure-(Armure).html&quot; title=&quot;Pointes d&amp;#39;armure&quot;&gt;pointes d&#39;armure&lt;/a&gt;, les d&#233;g&#226;ts sont bas&#233;s sur son &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; et pas sur l’arme, comme avec la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre-Combattant.html#ARMESACREE&quot; title=&quot;Le pr&#234;tre combattant&quot;&gt;arme sacr&#233;e&lt;/a&gt; du pr&#234;tre combattant. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#TOUCHERDECORRUPTION&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;toucher de corruption&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Dons suppl&#233;mentaires&lt;a class=&quot;headeranchor&quot; id=&quot;Dons_suppl&#233;mentaires_1&quot; href=&quot;#Dons_suppl&#233;mentaires_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 3 et tous les 3 niveaux d’antipaladin par la suite, un tyran de fer gagne un don suppl&#233;mentaire en plus de ceux offerts par sa progression normale. Il doit imp&#233;rativement les choisir parmi les &lt;a class=&quot;pagelink&quot; href=&quot;Dons.html#COMBAT&quot; title=&quot;Les dons&quot;&gt;dons de combat&lt;/a&gt; qui am&#233;liorent l&#39;armure ou le bouclier du tyran de fer, tels que &lt;a class=&quot;pagelink&quot; href=&quot;Art-Du-Bouclier.html&quot; title=&quot;Art du bouclier&quot;&gt;Art du bouclier&lt;/a&gt;, ou des &lt;a class=&quot;pagelink&quot; href=&quot;Dons.html#MAITRISEDARMURE&quot; title=&quot;Les dons&quot;&gt;dons de ma&#238;trise d’armure&lt;/a&gt;. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#CRUAUTE&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;cruaut&#233;&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Inarr&#234;table (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Inarr&#234;table_Ext_2&quot; href=&quot;#Inarr&#234;table_Ext_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 4, quand il porte une &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armures#Lourdes.html&quot; title=&quot;armure lourde&quot;&gt;armure lourde&lt;/a&gt;, un tyran de fer n’est pas ralenti par les terrains qui r&#233;duisent la vitesse de moiti&#233; (tel que des d&#233;combres denses, une v&#233;g&#233;tation l&#233;g&#232;re et des tourbi&#232;res peu profondes). Les terrains manipul&#233;s magiquement pour entraver le mouvement ou ceux r&#233;duisant de plus de moiti&#233; le d&#233;placement l’affectent normalement. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#CANALISATIONDENERGIENEGATIVE&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;canalisation d’&#233;nergie n&#233;gative&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Pacte fi&#233;lon (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Pacte_fi&#233;lon_Sur_3&quot; href=&quot;#Pacte_fi&#233;lon_Sur_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 5, au lieu d&#39;obtenir une faveur fi&#233;lonne sous la forme d&#39;une arme am&#233;lior&#233;e ou d&#39;un serveur, un tyran de fer forme un lien avec son armure. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, un tyran de fer peut enchanter son armure en invoquant l’aide d’un esprit fi&#233;lon. Ce lien dure 1 minute par niveau d’antipaladin. Lorsqu’il est appel&#233;, l’esprit enveloppe l’armure d’une lueur mal&#233;fique semblable &#224; celle d’une &lt;a class=&quot;pagelink&quot; href=&quot;Torche-(Objet).html&quot; title=&quot;Torche&quot;&gt;torche&lt;/a&gt;. &lt;br /&gt;&lt;br /&gt;Au niveau 5, l’esprit accorde un bonus d’alt&#233;ration de +1 &#224; l’armure. Tous les 3 niveaux d’antipaladin apr&#232;s le niveau 5, ce bonus augmente de +1, jusqu&#39;&#224; un maximum de +6 au niveau 20. Ces bonus se cumulent avec les bonus d’alt&#233;ration existant de l’armure jusqu&#39;&#224; un maximum de +5, ou peuvent &#234;tre utilis&#233;s pour ajouter l’une des propri&#233;t&#233;s sp&#233;ciales d&#39;armure suivantes : &lt;i&gt;d&#233;fense&lt;/i&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#D&#233;fense-(L&#233;g&#232;re).html&quot; title=&quot;d&#233;fense l&#233;g&#232;re (propri&#233;t&#233;)&quot;&gt;l&#233;g&#232;re&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#D&#233;fense-(Interm&#233;diaire).html&quot; title=&quot;d&#233;fense interm&#233;diaire (propri&#233;t&#233;)&quot;&gt;interm&#233;diaire&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#D&#233;fense-(Lourde).html&quot; title=&quot;d&#233;fense lourde (propri&#233;t&#233;)&quot;&gt;lourde&lt;/a&gt;), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Fourberie.html&quot; title=&quot;fourberie (propri&#233;t&#233;)&quot;&gt;fourberie&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Invuln&#233;rabilit&#233;.html&quot; title=&quot;invuln&#233;rabilit&#233; (propri&#233;t&#233;)&quot;&gt;invuln&#233;rabilit&#233;&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;r&#233;sistance &#224; la magie&lt;/i&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#R&#233;sistance-&#192;-La-Magie-(13).html&quot; title=&quot;r&#233;sistance &#224; la magie 13 (propri&#233;t&#233;)&quot;&gt;13&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#R&#233;sistance-&#192;-La-Magie-(15).html&quot; title=&quot;r&#233;sistance &#224; la magie 15 (propri&#233;t&#233;)&quot;&gt;15&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#R&#233;sistance-&#192;-La-Magie-(17).html&quot; title=&quot;r&#233;sistance &#224; la magie 17 (propri&#233;t&#233;)&quot;&gt;17&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#R&#233;sistance-&#192;-La-Magie-(19).html&quot; title=&quot;r&#233;sistance &#224; la magie 19 (propri&#233;t&#233;)&quot;&gt;19&lt;/a&gt;), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Spectrale.html&quot; title=&quot;spectrale (propri&#233;t&#233; armure)&quot;&gt;spectrale&lt;/a&gt;&lt;/i&gt;. Ajouter ces propri&#233;t&#233;s sp&#233;ciales consomme une quantit&#233; de bonus &#233;gal au prix du modificateur de base de la propri&#233;t&#233;. De plus, le tyran de fer peut accorder &#224; son armure la propri&#233;t&#233; sp&#233;ciale &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Impie.html&quot; title=&quot;impie (propri&#233;t&#233; armure)&quot;&gt;impie&lt;/a&gt;&lt;/i&gt; au prix d&#39;un bonus de +4. Ces propri&#233;t&#233;s s’ajoutent &#224; celles que l’armure poss&#232;de d&#233;j&#224; mais les doubles ne se cumulent pas. Si l’armure n’est pas magique, il faut au moins lui ajouter un bonus d’alt&#233;ration de +1 avant de pouvoir lui donner la moindre propri&#233;t&#233;.&lt;br /&gt;&lt;br /&gt;Les bonus et les propri&#233;t&#233;s sp&#233;ciales accord&#233;s par l’esprit sont d&#233;termin&#233;s quand l’esprit est appel&#233; et ne peuvent pas &#234;tre chang&#233;s tant que l’esprit n’est pas appel&#233; de nouveau. L’esprit fi&#233;lon n’accorde aucun bonus si l’armure est port&#233;e par quelqu’un d’autre que le tyran de fer, mais elle redonne ses bonus si le tyran remet l’armure. Un tyran de fer peut utiliser cette capacit&#233; 1 fois par jour au niveau 5, puis 1 fois de plus par jour tous les 4 niveaux apr&#232;s le niveau 5, pour un maximum de 4 fois par jour au niveau 17.&lt;br /&gt;&lt;br /&gt;Si une armure li&#233;e avec un esprit fi&#233;lon est d&#233;truite, le tyran de fer perd l&#39;utilisation de cette capacit&#233; pendant 30 jours, ou jusqu&#39;&#224; ce qu&#39;il gagne un niveau, selon ce qui arrive en premier. Durant cette p&#233;riode, le tyran de fer souffre d’un malus de -1 &#224; ses &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets d’attaque&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;de d&#233;g&#226;ts&lt;/a&gt;. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#FAVEURDESFIELONS&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;faveur des fi&#233;lons&lt;/a&gt;.
